 const[potDetail,setPotDetail]=useState<Array<{round:number,amount:number}>>([]);
 const[detailLoading,setDetailLoading]=useState(false);
 const[rankingLoading,setRankingLoading]=useState(true);
 useEffect(()=>{void(async()=>{const [{data:b},{data:p},{data:ps}]=await Promise.all([
  supabase.from("quini_standings").select("user_id,username,hits").order("hits",{ascending:false}),
  supabase.from("quini_pot_standings").select("user_id,username,pot_euros").order("pot_euros",{ascending:false}),
  supabase.from("quini_public_profiles").select("user_id,username,has_profile_pic")
 ]);const map:Record<string,{username:string,profile_pic:string}>={};for(const x of ps||[])map[x.user_id]={username:x.username,profile_pic:x.has_profile_pic?publicAvatar(x.user_id):""};try{const user=await currentSessionUser();if(user){const local=JSON.parse(localStorage.getItem("quiniderio-player")||"{}");const localPic=typeof local.profilePic==="string"?local.profilePic.trim():"";if(localPic&&map[user.id])map[user.id].profile_pic=localPic}}catch{}setProfiles(map);setBoard((b||[]) as any);setPot((p||[]) as any);setRankingLoading(false)})()},[]);
 const openPlayer=async(row:any)=>{setSelected(row);setDetail([]);setPotDetail([]);setDetailLoading(true);if(view==="pot"){const{data:finishedMatches}=await supabase.from("quini_live_matches").select("round,team,status");const byRound=new Map<number,{total:number,done:number}>();for(const m of finishedMatches||[]){const r=Number(m.round);const x=byRound.get(r)||{total:0,done:0};x.total++;if(["finished","final","suspended"].includes(String(m.status)))x.done++;byRound.set(r,x)}const rounds=[...byRound.entries()].filter(([,x])=>x.total>0&&x.done===x.total).map(([r])=>r).sort((a,b)=>a-b);const amounts:Array<{round:number,amount:number}>=[];for(const round of rounds){const {data:roundRows}=await supabase.from("quini_round_scores").select("user_id,hits,picks_count").eq("round",round);const rr=roundRows||[];const finishedCount=(await supabase.from("quini_live_matches").select("team",{count:"exact",head:true}).eq("round",round).eq("status","finished")).count||0;const sorted=[...new Set(rr.map((x:any)=>Number(x.hits)))].sort((a,b)=>a-b);const me=rr.find((x:any)=>x.user_id===row.user_id);let amount=0;if(me){if(Number(me.hits)===finishedCount&&Number(me.hits)>0)amount=-3;else{const rank=sorted.indexOf(Number(me.hits))+1;amount=rank===1?2:rank===2?1:0}}amounts.push({round:Number(round),amount})}setPotDetail(amounts)}else{const{data}=await supabase.from("quini_finished_pick_stats").select("round,team,pick,opponent,home_score,away_score,result").eq("user_id",row.user_id).order("round").order("team");setDetail((data||[]) as any)}setDetailLoading(false)};
 const rows=view==="hits"?board:pot;
 const profileFor=(row:any)=>profiles[row.user_id]||Object.values(profiles).find(p=>p.username?.trim().toLowerCase()===String(row.username||"").trim().toLowerCase());
 const correct=detail.filter(x=>x.pick===x.result).length,total=detail.length,pct=total?Math.round(correct/total*100):0;
 const rounds=[...new Set(detail.map(x=>x.round))]; const avg=rounds.length?correct/rounds.length:0;
 return <section className="tabPage"><div className="pageTop porraPageTop"><p className="eyebrow">CLASIFICACIÓN</p><h1>{view==="hits"?"Clasificación general":"Bote acumulado"}</h1><p>{view==="hits"?"Aciertos acumulados durante la temporada.":"Penalización acumulada de la temporada."}</p></div><div className="rankingTabs"><button className={view==="hits"?"active":""} onClick={()=>setView("hits")}>Aciertos</button><button className={view==="pot"?"active":""} onClick={()=>setView("pot")}>Bote acumulado</button></div>{rows.length?<><div className="rankingHeader"><span>#</span><span>JUGADOR</span><span>{view==="hits"?"ACIERTOS":"BOTE"}</span></div><div className="rankingRows">{rows.map((row:any,i)=>{const profile=profileFor(row);return <button type="button" className={"rankingRow rankingRowButton "+(view==="hits"?(i<Math.floor(rows.length/2)?"rankingUpper":i>=Math.ceil(rows.length/2)?"rankingLower":""):"")} onClick={()=>void openPlayer(row)} key={row.user_id||row.username}><span>{i+1}</span><b className="rankingPlayer"><span className="rankingAvatar">{profile?.profile_pic?<img src={profile.profile_pic} alt={row.username}/>:row.username?.[0]?.toUpperCase()}</span><span>{row.username}</span></b><strong>{view==="hits"?row.hits:row.pot_euros+" €"}</strong></button>})}</div></>:rankingLoading?<div className="rankingSkeleton" aria-label="Cargando clasificación">{Array.from({length:7},(_,i)=><div className="rankingSkeletonRow" key={i} style={{animationDelay:`${i*70}ms`}}><i/><span/><b/></div>)}</div>:null}
 {selected&&typeof document!=="undefined"&&createPortal(<div className="playerStatsOverlay" onClick={()=>setSelected(null)}><section className="playerStatsModal" onClick={e=>e.stopPropagation()}><header><div className="playerStatsIdentity"><span className="playerStatsAvatar">{profileFor(selected)?.profile_pic?<img src={profileFor(selected)?.profile_pic} alt={selected.username}/>:selected.username?.[0]?.toUpperCase()}</span><h2>{selected.username}</h2></div><button type="button" onClick={()=>setSelected(null)}>×</button></header>{detailLoading?<div className="playerStatsLoading">Cargando estadísticas…</div>:view==="pot"?<div className="playerPotDetail"><div className="playerMatchTitle"><div><span>BOTE ACUMULADO</span><b>Desglose por jornada</b></div></div>{potDetail.map(item=><article key={item.round}><b>J{item.round}</b><strong>{item.amount===0?"-":`${item.amount}€`}</strong></article>)}</div>:<><div className="playerStatsSummary"><article><b>{correct}</b><small>ACIERTOS</small></article><article><b>{avg.toLocaleString("es-ES",{minimumFractionDigits:2,maximumFractionDigits:2})}</b><small>MEDIA / JORNADA</small></article><article><b>{pct}%</b><small>% DE ACIERTO</small></article></div><p className="playerStatsCalculated">Calculado sobre {total} pronósticos de {rounds.length} jornadas finalizadas.</p><div className="playerMatchList"><div className="playerMatchTitle"><div><span>PRONÓSTICOS</span><b>Desglose general</b></div><small>{total}</small></div>{detail.length?detail.map((x,i)=>{const hit=x.pick===x.result;const game=(quizFixtures[x.round]?.[x.team]||{}) as any;const home=game.isHome===false?x.opponent:x.team,away=game.isHome===false?x.team:x.opponent;return <article className={hit?"hit":""} key={x.round+"-"+x.team+"-"+i}><div><small>J{x.round}</small><b>{home} <em>{x.home_score}-{x.away_score}</em> {away}</b></div><span><small>PRONÓSTICO</small><strong>{x.pick}</strong></span></article>}):<div className="playerStatsEmpty">Todavía no hay partidos finalizados para calcular estadísticas.</div>}</div></>}</section></div>,document.body)}
 </section>
